1	// pattern: Mixed (Functional Core sweep orchestration + iOS-only imperative scheduling bridge)
2	//
3	// Background media-backup scheduling. The user-held blob backup (`blob_backup.rs`) ships
4	// the explicit "Back up media" action plus an opportunistic pass on app open; this module
5	// adds the deliberate later step — an iOS `BGProcessingTask` so an opted-in identity's
6	// iCloud mirror stays topped up without the user opening the app (media posted days ago
7	// shouldn't sit unprotected until the next launch).
8	//
9	// On fire it runs the same incremental, CID-verified, per-blob-degrading `run_blob_backup`
10	// pass for every opted-in DID. That is safe to overlap with a foreground pass: the per-DID
11	// mirror lock in `blob_backup` serializes the manifest writes, and the pass is idempotent
12	// by construction (content-addressed, immutable files), so a sweep iOS interrupts mid-run
13	// self-heals on the next pass.
14	//
15	// Scheduling is a device concern: everything that touches `BGTaskScheduler` is iOS-only,
16	// reached through objc2's BackgroundTasks binding — the same no-new-Swift bridge pattern as
17	// blob_backup's ubiquity-container call. Off-device the scheduling surface is inert. The
18	// sweep *orchestration* (`run_sweep_with`) is platform-agnostic and unit-tested.
19	//
20	// The user tunes the sweep from Settings via three app-global flags
21	// (`BackgroundBackupSettings`): whether iOS may wake the app at all, whether to require
22	// external power, and whether to skip cellular links. They are app-global (not per-DID)
23	// because the sweep is one `BGProcessingTask` covering every opted-in identity. The
24	// settings get/set commands are frontend-facing, so they (and their harness fakes) are the
25	// one part of this module the browser harness does touch.
26	
27	use crate::blob_backup;
28	use serde::{Deserialize, Serialize};
29	
30	// ── User-tunable settings (app-global) ───────────────────────────────────────
31	
32	/// Global Keychain account holding the background-backup settings JSON. App-wide (not
33	/// per-DID): the sweep is one `BGProcessingTask` covering every opted-in identity, so its
34	/// power/network policy is a single shared setting.
35	const SETTINGS_ACCOUNT: &str = "blob-backup-settings";
36	
37	/// User-tunable policy for the background media-backup sweep. App-global. Serializes as
38	/// camelCase to match the `$lib/ipc` `BackgroundBackupSettings` type.
39	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
40	#[serde(rename_all = "camelCase")]
41	pub struct BackgroundBackupSettings {
42	    /// Whether iOS may wake the app to run a backup sweep at all. Off keeps the
43	    /// opportunistic app-open pass but stops OS-scheduled wakes.
44	    pub background_enabled: bool,
45	    /// Only run the sweep while the device is on external power (charging). Off by default
46	    /// so the sweep isn't starved on devices that rarely charge on a predictable schedule.
47	    pub require_external_power: bool,
48	    /// Skip the sweep on a cellular (metered) link — a video-heavy account's mirror can be
49	    /// large. Enforced at fire time via a reachability check (`BGProcessingTaskRequest`
50	    /// can't express "Wi-Fi only").
51	    pub wifi_only: bool,
52	}
53	
54	impl Default for BackgroundBackupSettings {
55	    fn default() -> Self {
56	        Self {
57	            background_enabled: true,
58	            require_external_power: false,
59	            wifi_only: false,
60	        }
61	    }
62	}
63	
64	/// Error from the background-backup settings commands. Serializes as
65	/// `{ "code": "SCREAMING_SNAKE_CASE" }` like the sibling wallet error enums.
66	#[derive(Debug, Serialize, thiserror::Error)]
67	#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE")]
68	pub enum BackgroundBackupError {
69	    #[error("keychain error: {message}")]
70	    KeychainError { message: String },
71	    #[error("could not encode settings: {message}")]
72	    SerializationError { message: String },
73	}
74	
75	/// Read the persisted settings, or the defaults when unset or unreadable. A corrupt/
76	/// unreadable value reads as the defaults (background on), never an error — a diagnostic
77	/// hiccup must not silently disable a backup the user relies on.
78	pub(crate) fn load_settings() -> BackgroundBackupSettings {
79	    crate::keychain::get_item(SETTINGS_ACCOUNT)
80	        .ok()
81	        .and_then(|raw| serde_json::from_slice(&raw).ok())
82	        .unwrap_or_default()
83	}
84	
85	/// Tauri command: the current background-backup settings, for the Settings screen.
86	#[tauri::command]
87	pub fn get_background_backup_settings() -> BackgroundBackupSettings {
88	    load_settings()
89	}
90	
91	/// Tauri command: persist the background-backup settings and re-apply the schedule (on iOS:
92	/// submit or cancel the `BGProcessingTask` to match `background_enabled` /
93	/// `require_external_power`; `wifi_only` needs no reschedule — it is read at fire time).
94	/// Returns the stored settings.
95	#[tauri::command]
96	pub fn set_background_backup_settings(
97	    settings: BackgroundBackupSettings,
98	) -> Result<BackgroundBackupSettings, BackgroundBackupError> {
99	    let json =
100	        serde_json::to_vec(&settings).map_err(|e| BackgroundBackupError::SerializationError {
101	            message: e.to_string(),
102	        })?;
103	    crate::keychain::store_item(SETTINGS_ACCOUNT, &json).map_err(|e| {
104	        BackgroundBackupError::KeychainError {
105	            message: e.to_string(),
106	        }
107	    })?;
108	    #[cfg(target_os = "ios")]
109	    apply_schedule();
110	    Ok(settings)
111	}
112	
113	/// Whether the sweep should be skipped this run for network policy: `wifi_only` is on and
114	/// we are on a cellular (metered) link. Pure so the decision is unit-tested; the live
115	/// cellular check (`on_cellular`) is the iOS-only side effect.
116	#[cfg_attr(not(target_os = "ios"), allow(dead_code))]
117	pub(crate) fn should_skip_for_network(wifi_only: bool, on_cellular: bool) -> bool {
118	    wifi_only && on_cellular
119	}
120	
121	/// The `BGTaskScheduler` identifier for the media-backup processing task. MUST match the
122	/// entry in `Info.ios.plist`'s `BGTaskSchedulerPermittedIdentifiers` array — iOS refuses to
123	/// register or submit an identifier the plist doesn't permit — and is bundle-id-prefixed by
124	/// Apple convention (bundle id `dev.malpercio.identitywallet`, `tauri.conf.json`). Kept in
125	/// sync with the plist the same way the ubiquity container id is.
126	#[cfg(target_os = "ios")]
127	const BACKUP_TASK_IDENTIFIER: &str = "dev.malpercio.identitywallet.blob-backup";
128	
129	/// The earliest the system may run a scheduled task, as a delay from submission. A floor,
130	/// not a deadline — iOS picks the actual moment from usage, power, and network availability.
131	/// ~12h keeps the mirror fresh (new media is protected within a day) without asking to wake
132	/// more often than a media backup needs to.
133	#[cfg(target_os = "ios")]
134	const EARLIEST_BEGIN_AFTER_SECS: f64 = 12.0 * 60.0 * 60.0;
135	
136	/// Summary of one background sweep — counts only, for `tracing` and the unit tests.
137	#[cfg_attr(not(target_os = "ios"), allow(dead_code))]
138	#[derive(Debug, Default, PartialEq, Eq)]
139	pub(crate) struct BackupSweepReport {
140	    /// Opted-in identities the sweep attempted a pass for.
141	    pub attempted: u32,
142	    /// Attempts that completed without error.
143	    pub succeeded: u32,
144	    /// Attempts that returned an error (logged, never aborts the sweep).
145	    pub failed: u32,
146	    /// Identities skipped because the user has not opted in.
147	    pub skipped: u32,
148	}
149	
150	/// Sweep core: back up every opted-in identity, degrading per-DID — one identity's failure
151	/// is tallied and logged, never stops the others. Generic over the opt-in predicate and the
152	/// per-DID backup step so it is unit-testable without a live PDS, Keychain, or iCloud.
153	/// Sequential by design: the passes share the network and the process-global per-DID mirror
154	/// locks, and a background sweep has no reason to race them concurrently.
155	#[cfg_attr(not(target_os = "ios"), allow(dead_code))]
156	pub(crate) async fn run_sweep_with<F, Fut>(
157	    dids: &[String],
158	    is_enabled: impl Fn(&str) -> bool,
159	    backup_one: F,
160	) -> BackupSweepReport
161	where
162	    F: Fn(String) -> Fut,
163	    Fut: std::future::Future<Output = Result<(), blob_backup::BlobBackupError>>,
164	{
165	    let mut report = BackupSweepReport::default();
166	    for did in dids {
167	        if !is_enabled(did) {
168	            report.skipped += 1;
169	            continue;
170	        }
171	        report.attempted += 1;
172	        match backup_one(did.clone()).await {
173	            Ok(()) => report.succeeded += 1,
174	            Err(e) => {
175	                tracing::warn!(did = %did, error = %e, "background media backup: pass failed");
176	                report.failed += 1;
177	            }
178	        }
179	    }
180	    report
181	}
182	
183	/// Run one background backup sweep over every managed identity, backing up those opted in.
184	/// The launch handler's payload. Resolves the managed DIDs from the `IdentityStore` and
185	/// delegates to `run_sweep_with` with the real opt-in flag + per-DID backup.
186	#[cfg(target_os = "ios")]
187	pub(crate) async fn run_backup_sweep(app: &tauri::AppHandle) -> BackupSweepReport {
188	    // Honor the Wi-Fi-only preference: BGProcessingTaskRequest can't express "Wi-Fi only", so
189	    // we check the live network type here and defer to the next scheduled fire if on cellular.
190	    let settings = load_settings();
191	    if should_skip_for_network(settings.wifi_only, on_cellular()) {
192	        tracing::info!(
193	            "background media backup: skipped this run — Wi-Fi only is on and the device is on cellular"
194	        );
195	        return BackupSweepReport::default();
196	    }
197	
198	    let dids = crate::identity_store::IdentityStore
199	        .list_identities()
200	        .unwrap_or_default();
201	    let report = run_sweep_with(
202	        &dids,
203	        |did| blob_backup::is_backup_enabled(did),
204	        |did| {
205	            let app = app.clone();
206	            async move {
207	                blob_backup::run_backup_for_did(&app, &did)
208	                    .await
209	                    .map(|_| ())
210	            }
211	        },
212	    )
213	    .await;
214	    tracing::info!(
215	        attempted = report.attempted,
216	        succeeded = report.succeeded,
217	        failed = report.failed,
218	        skipped = report.skipped,
219	        "background media backup sweep complete"
220	    );
221	    report
222	}
223	
224	// ── iOS BGProcessingTask bridge ──────────────────────────────────────────────
225	
226	/// A `Retained<BGTask>` we promise to use soundly across threads.
227	///
228	/// iOS calls the launch handler on the main thread, but the backup sweep runs on the tokio
229	/// runtime; the worker (or the expiration handler) must call `setTaskCompletedWithSuccess`
230	/// when it finishes. objc2 conservatively leaves framework objects `!Send`, so we assert it.
231	///
232	/// SAFETY: the only `BGTask` methods we call on it are the completion methods, which Apple
233	/// documents as callable from any thread (their sample code completes the task from an
234	/// `NSOperation` completion block on a background queue), and every such call is gated behind
235	/// a one-shot atomic latch so it happens exactly once.
236	#[cfg(target_os = "ios")]
237	struct SendTask(objc2::rc::Retained<objc2_background_tasks::BGTask>);
238	
239	#[cfg(target_os = "ios")]
240	// SAFETY: see the `SendTask` doc comment — completion methods are thread-safe by Apple's
241	// contract and serialized to a single call by the `done` latch in `complete_once`.
242	unsafe impl Send for SendTask {}
243	#[cfg(target_os = "ios")]
244	// SAFETY: as above; the shared handle is only ever used to make the thread-safe completion
245	// call, so concurrent `&SendTask` access from the worker and the expiration handler is sound.
246	unsafe impl Sync for SendTask {}
247	
248	/// Mark the task complete at most once — whichever of the worker (success) or the expiration
249	/// handler (failure) reaches it first wins; the loser is a no-op. iOS treats a second
250	/// `setTaskCompletedWithSuccess` on the same task as a fatal misuse, so the latch is required.
251	#[cfg(target_os = "ios")]
252	fn complete_once(task: &SendTask, done: &std::sync::atomic::AtomicBool, success: bool) {
253	    use std::sync::atomic::Ordering;
254	    if !done.swap(true, Ordering::SeqCst) {
255	        unsafe { task.0.setTaskCompletedWithSuccess(success) };
256	    }
257	}
258	
259	/// Register the background media-backup task and submit the first request. Called once from
260	/// the Tauri `setup` hook on iOS — registration must happen before app launch completes, and
261	/// `setup` runs within `application:didFinishLaunchingWithOptions:`. Every failure is logged
262	/// rather than fatal: the opportunistic app-open pass still protects opted-in identities.
263	#[cfg(target_os = "ios")]
264	pub(crate) fn register_and_schedule(app: &tauri::AppHandle) {
265	    use block2::RcBlock;
266	    use objc2_background_tasks::{BGTask, BGTaskScheduler};
267	    use objc2_foundation::NSString;
268	    use std::ptr::NonNull;
269	
270	    let scheduler = unsafe { BGTaskScheduler::sharedScheduler() };
271	    let identifier = NSString::from_str(BACKUP_TASK_IDENTIFIER);
272	
273	    let app_for_handler = app.clone();
274	    // Escaping launch handler; iOS stores a copy for the process lifetime and calls it on the
275	    // main thread when it decides to run the task, handing us the live `BGTask`.
276	    let launch_handler = RcBlock::new(move |task_ptr: NonNull<BGTask>| {
277	        // We were handed the task with no ownership; retain it (+1) so it survives the async
278	        // sweep. Non-null by the framework's contract.
279	        let Some(task) = (unsafe { objc2::rc::Retained::retain(task_ptr.as_ptr()) }) else {
280	            return;
281	        };
282	        handle_launch(&app_for_handler, task);
283	    });
284	
285	    let registered = unsafe {
286	        scheduler.registerForTaskWithIdentifier_usingQueue_launchHandler(
287	            &identifier,
288	            None, // run the launch handler on the default background queue
289	            &launch_handler,
290	        )
291	    };
292	    if !registered {
293	        tracing::warn!(
294	            "background media backup: BGTaskScheduler refused to register the task identifier"
295	        );
296	        return;
297	    }
298	
299	    apply_schedule();
300	}
301	
302	/// Submit or cancel the `BGProcessingTask` request to match the current settings: a pending
303	/// request when background backups are enabled (carrying the external-power preference), or
304	/// none when they're off. Called at launch, whenever the settings change, and to re-arm the
305	/// next run as the task fires. The launch handler must already be registered.
306	#[cfg(target_os = "ios")]
307	fn apply_schedule() {
308	    use objc2_background_tasks::BGTaskScheduler;
309	    use objc2_foundation::NSString;
310	
311	    let scheduler = unsafe { BGTaskScheduler::sharedScheduler() };
312	    let identifier = NSString::from_str(BACKUP_TASK_IDENTIFIER);
313	    let settings = load_settings();
314	    if settings.background_enabled {
315	        schedule_next(&scheduler, &identifier, settings.require_external_power);
316	    } else {
317	        // Drop any pending request so a disabled setting takes effect immediately.
318	        unsafe { scheduler.cancelTaskRequestWithIdentifier(&identifier) };
319	    }
320	}
321	
322	/// Whether the device's default route is currently a cellular (WWAN) link, via
323	/// `SCNetworkReachability` flags for the unspecified address (general internet reachability).
324	/// On any read failure we report `false` (not cellular) so a diagnostic hiccup never silently
325	/// disables backups — an occasional cellular sweep is the lesser evil than a mirror that
326	/// quietly stops updating.
327	#[cfg(target_os = "ios")]
328	fn on_cellular() -> bool {
329	    use std::net::{Ipv4Addr, SocketAddr};
330	    use system_configuration::network_reachability::{ReachabilityFlags, SCNetworkReachability};
331	
332	    let addr = SocketAddr::from((Ipv4Addr::UNSPECIFIED, 0));
333	    let reachability = SCNetworkReachability::from(addr);
334	    match reachability.reachability() {
335	        Ok(flags) => {
336	            flags.contains(ReachabilityFlags::REACHABLE)
337	                && flags.contains(ReachabilityFlags::IS_WWAN)
338	        }
339	        Err(e) => {
340	            tracing::warn!(error = ?e, "background media backup: could not read network type; assuming not cellular");
341	            false
342	        }
343	    }
344	}
345	
346	/// The launch-handler body (runs on the main thread): re-arm the next run, then kick off the
347	/// sweep on the tokio runtime and wire up completion + expiration.
348	#[cfg(target_os = "ios")]
349	fn handle_launch(
350	    app: &tauri::AppHandle,
351	    task: objc2::rc::Retained<objc2_background_tasks::BGTask>,
352	) {
353	    use block2::RcBlock;
354	    use std::sync::atomic::AtomicBool;
355	    use std::sync::Arc;
356	
357	    // Re-arm the follow-up immediately (Apple's guidance is to submit the next request as the
358	    // task begins), so the mirror keeps getting topped up run after run. Via `apply_schedule`
359	    // so a disable toggled between fires cancels instead of re-submitting.
360	    apply_schedule();
361	
362	    // Share the task + a one-shot completion latch between the worker and the expiration
363	    // handler so the task is marked complete exactly once.
364	    let task = Arc::new(SendTask(task));
365	    let done = Arc::new(AtomicBool::new(false));
366	
367	    // Run the actual sweep off the main thread.
368	    let worker = {
369	        let app = app.clone();
370	        let task = task.clone();
371	        let done = done.clone();
372	        tauri::async_runtime::spawn(async move {
373	            let _ = run_backup_sweep(&app).await;
374	            complete_once(&task, &done, true);
375	        })
376	    };
377	
378	    // iOS calls this (on the main thread) when our time is nearly up: abort the sweep and end
379	    // cleanly. Aborting mid-pass is safe — the mirror write is atomic and the manifest is
380	    // checkpointed, so the interrupted DID simply resumes on the next sweep.
381	    let expiration = {
382	        let task = task.clone();
383	        RcBlock::new(move || {
384	            worker.abort();
385	            complete_once(&task, &done, false);
386	        })
387	    };
388	    unsafe { task.0.setExpirationHandler(Some(&expiration)) };
389	}
390	
391	/// Build and submit the next `BGProcessingTaskRequest`. Failures (the simulator has no
392	/// `BGTaskScheduler`; an unpermitted identifier; too many pending requests) are logged, never
393	/// fatal.
394	#[cfg(target_os = "ios")]
395	fn schedule_next(
396	    scheduler: &objc2_background_tasks::BGTaskScheduler,
397	    identifier: &objc2_foundation::NSString,
398	    require_external_power: bool,
399	) {
400	    use objc2::AnyThread;
401	    use objc2_background_tasks::BGProcessingTaskRequest;
402	    use objc2_foundation::NSDate;
403	
404	    let request = unsafe {
405	        BGProcessingTaskRequest::initWithIdentifier(BGProcessingTaskRequest::alloc(), identifier)
406	    };
407	    unsafe {
408	        // The sweep fetches blobs, so it always needs the network. External power follows the
409	        // user's "only while charging" setting (off by default so the sweep isn't starved on
410	        // devices that rarely charge on a predictable schedule). "Wi-Fi only" can't be
411	        // expressed here — it is enforced at fire time in `run_backup_sweep`.
412	        request.setRequiresNetworkConnectivity(true);
413	        request.setRequiresExternalPower(require_external_power);
414	        let earliest = NSDate::dateWithTimeIntervalSinceNow(EARLIEST_BEGIN_AFTER_SECS);
415	        request.setEarliestBeginDate(Some(&earliest));
416	    }
417	
418	    // A `BGProcessingTaskRequest` is a `BGTaskRequest`; `submitTaskRequest_error` takes the
419	    // superclass (deref coercion).
420	    if let Err(e) = unsafe { scheduler.submitTaskRequest_error(&request) } {
421	        tracing::warn!(error = ?e, "background media backup: failed to submit task request");
422	    }
423	}
424	
425	// ── Tests ────────────────────────────────────────────────────────────────────
426	
427	#[cfg(test)]
428	mod tests {
429	    use super::*;
430	    use blob_backup::BlobBackupError;
431	    use std::sync::atomic::{AtomicUsize, Ordering};
432	    use std::sync::Mutex;
433	
434	    fn dids(names: &[&str]) -> Vec<String> {
435	        names.iter().map(|s| s.to_string()).collect()
436	    }
437	
438	    #[tokio::test]
439	    async fn sweep_backs_up_only_opted_in_identities() {
440	        let all = dids(&["did:plc:a", "did:plc:b", "did:plc:c"]);
441	        // b is opted out.
442	        let enabled = |did: &str| did != "did:plc:b";
443	        let backed_up = Mutex::new(Vec::new());
444	
445	        let report = run_sweep_with(&all, enabled, |did| {
446	            let backed_up = &backed_up;
447	            async move {
448	                backed_up.lock().unwrap().push(did);
449	                Ok(())
450	            }
451	        })
452	        .await;
453	
454	        assert_eq!(
455	            report,
456	            BackupSweepReport {
457	                attempted: 2,
458	                succeeded: 2,
459	                failed: 0,
460	                skipped: 1,
461	            }
462	        );
463	        assert_eq!(
464	            *backed_up.lock().unwrap(),
465	            vec!["did:plc:a".to_string(), "did:plc:c".to_string()]
466	        );
467	    }
468	
469	    #[tokio::test]
470	    async fn sweep_degrades_per_did_and_continues() {
471	        let all = dids(&["did:plc:a", "did:plc:b", "did:plc:c"]);
472	        let attempts = AtomicUsize::new(0);
473	
474	        // The middle identity fails; the sweep must still attempt the third.
475	        let report = run_sweep_with(
476	            &all,
477	            |_| true,
478	            |did| {
479	                let attempts = &attempts;
480	                async move {
481	                    attempts.fetch_add(1, Ordering::SeqCst);
482	                    if did == "did:plc:b" {
483	                        Err(BlobBackupError::NetworkError {
484	                            message: "boom".to_string(),
485	                        })
486	                    } else {
487	                        Ok(())
488	                    }
489	                }
490	            },
491	        )
492	        .await;
493	
494	        assert_eq!(attempts.load(Ordering::SeqCst), 3);
495	        assert_eq!(
496	            report,
497	            BackupSweepReport {
498	                attempted: 3,
499	                succeeded: 2,
500	                failed: 1,
501	                skipped: 0,
502	            }
503	        );
504	    }
505	
506	    #[tokio::test]
507	    async fn sweep_with_no_opted_in_identities_does_nothing() {
508	        let all = dids(&["did:plc:a", "did:plc:b"]);
509	        let called = AtomicUsize::new(0);
510	
511	        let report = run_sweep_with(
512	            &all,
513	            |_| false,
514	            |did| {
515	                let called = &called;
516	                async move {
517	                    called.fetch_add(1, Ordering::SeqCst);
518	                    let _ = did;
519	                    Ok(())
520	                }
521	            },
522	        )
523	        .await;
524	
